// `npm run gen:edge-kernels`. Imported by customer-portal, drive-link, gc-trade-portal, gmail-sync, messages-email, messages-notify, messages-nudge-dispatch, photo-save, quo-send, quo-webhook, send-estimate-to-customer (the schedule's PR 14b).
/**
 * Messages, cut 5: the morning run's clock and its summary (`messages-nudge-dispatch`). The cron fires at 14:00 and
 * 15:00 UTC, so one tick is 9 AM Central in summer and the other in winter, and `runHourNow` says which one runs. The
 * summary is what the run returns, logs and keeps in `app_settings` `messages_nudge_last_run_v1`: what went, what was
 * kept back and why (the step's own switch, or Send texts off company-wide), what did not go, and who the run left out.
 * The owner reads it first. Pure.
 */
import { APP_CALENDAR_TZ } from '../../utils/dateUtils.ts'
import type { NudgeNotSent, NudgeRun } from './nudgeDispatch.ts'

/** The run's hour in the app's zone: the prototype's "at 9 AM that day". */
export const RUN_HOUR = 9

/** How many texts that did not go the summary keeps, so the row stays small. */
export const SUMMARY_REFUSED_MAX = 20

/** Whether this tick is the run's hour, 9 AM Central. */
export function runHourNow(now: Date): boolean {
  const hour = new Intl.DateTimeFormat('en-US', { timeZone: APP_CALENDAR_TZ, hour: '2-digit', hourCycle: 'h23' }).formatToParts(now).find((p) => p.type === 'hour')?.value
  return Number(hour) % 24 === RUN_HOUR
}

/** A text the run planned that did not go: Quo or the send turned it away, with its words. */
export interface RunRefused {
  contactId: string
  stepId: string
  words: string
}

/** The morning's run, as kept in `messages_nudge_last_run_v1`. */
export interface RunSummary {
  /** When it ran, an ISO timestamp. */
  at: string
  /** A dry run planned and wrote nothing. */
  dry: boolean
  /** Texts that went, or on a dry run would go. */
  sent: number
  /** Reminders kept back, by why. */
  kept: Partial<Record<NudgeNotSent, number>>
  /** Texts kept back because Settings → Phone and texts → Send texts is off (`sendText`'s `textsOff`). */
  textsOff: number
  /** Texts that did not go, the first `SUMMARY_REFUSED_MAX`. */
  refused: RunRefused[]
  /** How many texts did not go in all. */
  refusedCount: number
  /** People whose rows did not come back. */
  unread: number
  /** Customers left out because the run cannot read their page yet. */
  customersHeld: number
  /** Texts prepared for the office to press on Today's sends (v2.5595), one `nudge_offers` row each. */
  prepared: number
  /** Texts the office prepared for this morning that went (Send in the morning); counted in `sent` too. */
  morningSent: number
  /** The summary in plain words, one sentence each. */
  words: string[]
}

/** The reasons in the order the summary says them. */
const KEPT_ORDER: readonly NudgeNotSent[] = ['off', 'offered', 'not a text', 'snoozed', 'sent lately', 'no number', 'opted out', 'prefers email', 'one a morning']

/** Why a reminder was kept back, after "because". */
const KEPT_WHY: Readonly<Record<NudgeNotSent, string>> = {
  off: 'the app does not send that step yet',
  offered: 'a text for that step already waits on Today’s sends',
  'not a text': 'its reminder is a call or an email',
  snoozed: 'the person is snoozed on Follow up',
  'sent lately': 'someone reminded them inside the step’s days',
  'no number': 'there is no number on file',
  'opted out': 'the number sent STOP',
  'prefers email': 'they asked to hear from us by email',
  'one a morning': 'that person already gets a text this morning',
}

const many = (n: number, one: string, more: string): string => `${n} ${n === 1 ? one : more}`

/** The summary's sentences. */
export function summaryWords(s: Omit<RunSummary, 'words'>): string[] {
  const words: string[] = []
  if (s.dry) words.push('A dry run. Nothing went and nothing was written.')
  if (s.dry) words.push(s.sent === 0 ? 'No text would go.' : `${many(s.sent, 'text', 'texts')} would go.`)
  else words.push(s.sent === 0 ? 'No text went.' : `${many(s.sent, 'text', 'texts')} went.`)
  if (s.morningSent) words.push(`${many(s.morningSent, 'text', 'texts')} the office prepared for this morning went.`)
  if (s.prepared) words.push(s.dry ? `${many(s.prepared, 'text', 'texts')} would be prepared for Today’s sends.` : `${many(s.prepared, 'text was', 'texts were')} prepared for Today’s sends.`)
  for (const why of KEPT_ORDER) {
    const n = s.kept[why] ?? 0
    if (n) words.push(`${many(n, 'reminder was', 'reminders were')} kept back because ${KEPT_WHY[why]}.`)
  }
  if (s.textsOff) words.push(`${many(s.textsOff, 'text was', 'texts were')} kept back because Send texts is off in Settings.`)
  if (s.refusedCount) words.push(`${many(s.refusedCount, 'text', 'texts')} did not go.`)
  if (s.unread) words.push(`${many(s.unread, 'person', 'people')} could not be read, so the run left them out.`)
  if (s.customersHeld) words.push('Customers wait until the run can read their page.')
  return words
}

/** The morning's summary from the plan and what the sends did. */
export function runSummary(i: {
  run: NudgeRun
  sent: number
  refused: readonly RunRefused[]
  /** Texts `sendText` kept back as `textsOff`. */
  textsOff?: number
  unread: number
  customersHeld: number
  /** Texts written to `nudge_offers` for the office to press; on a dry run, the texts that would be. */
  prepared?: number
  /** Texts the office prepared for this morning that went. */
  morningSent?: number
  now: Date
  dry: boolean
}): RunSummary {
  const kept: Partial<Record<NudgeNotSent, number>> = {}
  for (const k of i.run.notSent) kept[k.why] = (kept[k.why] ?? 0) + 1
  const base = {
    at: i.now.toISOString(),
    dry: i.dry,
    sent: i.sent,
    kept,
    textsOff: i.textsOff ?? 0,
    refused: i.refused.slice(0, SUMMARY_REFUSED_MAX),
    refusedCount: i.refused.length,
    unread: i.unread,
    customersHeld: i.customersHeld,
    prepared: i.prepared ?? 0,
    morningSent: i.morningSent ?? 0,
  }
  return { ...base, words: summaryWords(base) }
}
